import React, { useState } from "react";

function Leaderboard() {
  const [usernamesInput, setUsernamesInput] = useState("");
  const [data, setData] = useState([]);
  const [loading, setLoading] = useState(false);

  const handleFetch = async () => {
    const usernames = usernamesInput
      .split(",")
      .map((name) => name.trim())
      .filter((name) => name !== "");

    if (usernames.length === 0) return;

    setLoading(true);

    const results = await Promise.all(
      usernames.map(async (username) => {
        const query = {
          query: `
            query userSessionProgress($username: String!) {
              matchedUser(username: $username) {
                submitStats {
                  acSubmissionNum {
                    difficulty
                    count
                  }
                }
              }
              userContestRanking(username: $username) {
                rating
              }
            }
          `,
          variables: { username },
        };

        try {
          const res = await fetch("http://localhost:4000/api/leetcode", {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify(query),
          });

          const json = await res.json();
          const user = json.data.matchedUser;
          const rating = json.data.userContestRanking?.rating || "N/A";
          const acStats = user?.submitStats?.acSubmissionNum || [];

          const getCount = (difficulty) =>
            acStats.find((x) => x.difficulty === difficulty)?.count || 0;

          const problemsSolved = getCount("All");
          const easy = getCount("Easy");
          const medium = getCount("Medium");
          const hard = getCount("Hard");

          return {
            name: username,
            problemsSolved,
            easy,
            medium,
            hard,
            contestRating: rating,
          };
        } catch (error) {
          return {
            name: username,
            problemsSolved: 0,
            easy: 0,
            medium: 0,
            hard: 0,
            contestRating: "Error",
          };
        }
      })
    );

    const sorted = results.sort((a, b) => b.problemsSolved - a.problemsSolved);
    setData(sorted);
    setLoading(false);
  };

  return (
    <div className="bg-white rounded-2xl shadow p-4 max-w-5xl mx-auto">
      <h2 className="text-2xl font-bold mb-4 text-center">LeetCode Leaderboard</h2>
      <div className="mb-4">
        <input
          type="text"
          placeholder="Enter usernames separated by commas"
          value={usernamesInput}
          onChange={(e) => setUsernamesInput(e.target.value)}
          className="border p-2 rounded w-full"
        />
        <button
          onClick={handleFetch}
          className="mt-2 bg-blue-500 text-white px-4 py-2 rounded hover:bg-blue-600"
        >
          Generate Leaderboard
        </button>
      </div>

      {loading && <p className="text-center text-lg">Loading...</p>}

      {data.length > 0 && (
        <table className="min-w-full table-auto mt-6 text-sm md:text-base">
          <thead>
            <tr className="bg-blue-100">
              <th className="px-2 py-2 text-left">Rank</th>
              <th className="px-2 py-2 text-left">Name</th>
              <th className="px-2 py-2 text-left">Total</th>
              <th className="px-2 py-2 text-left text-green-600">Easy</th>
              <th className="px-2 py-2 text-left text-yellow-600">Medium</th>
              <th className="px-2 py-2 text-left text-red-600">Hard</th>
              <th className="px-2 py-2 text-left">Rating</th>
            </tr>
          </thead>
          <tbody>
            {data.map((user, index) => (
              <tr key={index} className="border-b hover:bg-gray-50">
                <td className="px-2 py-2">{index + 1}</td>
                <td className="px-2 py-2 font-medium">{user.name}</td>
                <td className="px-2 py-2">{user.problemsSolved}</td>
                <td className="px-2 py-2 text-green-600">{user.easy}</td>
                <td className="px-2 py-2 text-yellow-600">{user.medium}</td>
                <td className="px-2 py-2 text-red-600">{user.hard}</td>
                <td className="px-2 py-2">{user.contestRating}</td>
              </tr>
            ))}
          </tbody>
        </table>
      )}
    </div>
  );
}

export default Leaderboard;
